public int square(int n) {
  return n * n;
}

public boolean isEven(int n) {
  return n % 2 == 0;
}

public int max(int a, int b) {
  if (a > b) {
    return a;
  } else {
    return b;
  }
}

public int factorial(int n) {
  int res = 1;
  for (int i = 1; i <= n; i++) {
    res *= i;
  }
  return res;
}

public double area(double r) {
  return r * r * Math.PI;
}
